import * as T from './vendor/three.module.js';
import {installEditor} from './world-editor.js';
import {OrbitControls} from './vendor/OrbitControls.js';
import {prepareArt,buildWorld} from './photo-world.js';
const views=new Map(),observed=new Set();
function dispose(view){view.removeEditor?.();view.controls.dispose();view.resize.disconnect();view.scene.traverse(o=>{if(o.geometry)o.geometry.dispose();if(o.material)for(const m of Array.isArray(o.material)?o.material:[o.material]){m.map?.dispose();m.dispose();}});view.renderer.dispose();view.renderer.forceContextLoss();view.renderer.domElement.remove();views.delete(view.element);}
const pending=new Set();
async function mount(element){if(views.has(element)||pending.has(element)||!element.isConnected)return;pending.add(element);try{
 const theme=element.dataset.worldTheme,ids=(element.dataset.worldOwned||'').split(',').filter(Boolean),catalog=globalThis.CATALOG.find(t=>t.id===theme);if(!catalog)return;const items=ids.map(id=>catalog.items.find(it=>it.id===id)).filter(Boolean);
 const art=await prepareArt(theme,items);if(!element.isConnected||element.dataset.worldVisible==='0')return;
 const renderer=new T.WebGLRenderer({antialias:true,alpha:false,powerPreference:'low-power'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFShadowMap;renderer.outputColorSpace=T.SRGBColorSpace;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1.2;
 const player=JSON.parse(element.dataset.worldState||'null');const scene=buildWorld(theme,items,art,player?.placements||{}),camera=new T.PerspectiveCamera(38,1,.1,180),distance=scene.userData.range;camera.position.set(distance*.28,distance*.7,distance*.98);
 element.prepend(renderer.domElement);const controls=new OrbitControls(camera,renderer.domElement);controls.target.set(0,scene.userData.targetY,0);controls.enableDamping=true;controls.enablePan=false;controls.enableZoom=false;controls.minDistance=distance*.4;controls.maxDistance=distance*2;controls.maxPolarAngle=Math.PI*.47;controls.update();
 const view={element,renderer,scene,camera,controls,player,dirty:true};controls.addEventListener('change',()=>view.dirty=true);const resize=new ResizeObserver(()=>{const w=element.clientWidth,h=element.clientHeight;if(!w||!h)return;renderer.setSize(w,h);camera.aspect=w/h;camera.updateProjectionMatrix();view.dirty=true;});view.resize=resize;resize.observe(element);view.removeEditor=installEditor(view,player);views.set(element,view);element.classList.add('ready');element.querySelector('.world-loading')?.remove();
 for(const button of element.querySelectorAll('[data-world-zoom]'))button.onclick=e=>{e.stopPropagation();camera.position.sub(controls.target).multiplyScalar(button.dataset.worldZoom==='in'?.82:1.22).add(controls.target);controls.update();view.dirty=true;};
 const reset=element.querySelector('[data-world-reset]');if(reset)reset.onclick=()=>{camera.position.set(distance*.28,distance*.7,distance*.98);controls.update();view.dirty=true;};
 }catch(e){element.classList.add('world-error');const label=element.querySelector('.world-loading');if(label)label.textContent='3B görünüm açılamadı. Güncel Chrome veya Safari ile tekrar dene.';console.error('3d-scene',e);}finally{pending.delete(element);}}
const observer=new IntersectionObserver(entries=>{for(const e of entries){e.target.dataset.worldVisible=e.isIntersecting?'1':'0';if(e.isIntersecting)mount(e.target);else{const v=views.get(e.target);if(v)dispose(v);}}},{rootMargin:'120px'});
function scan(){for(const el of observed)if(!el.isConnected){observer.unobserve(el);observed.delete(el);}for(const [el,v] of views)if(!el.isConnected)dispose(v);for(const el of document.querySelectorAll('[data-world-theme]:not([data-world-observed])')){el.dataset.worldObserved='1';observed.add(el);observer.observe(el);}}
new MutationObserver(scan).observe(document.body,{childList:true,subtree:true});scan();
function frame(time){if(!document.hidden)for(const v of views.values()){v.controls.update();if(v.scene.userData.animate?.(time/1000))v.dirty=true;if(v.dirty){v.renderer.render(v.scene,v.camera);v.dirty=false;}}requestAnimationFrame(frame);}requestAnimationFrame(frame);
document.addEventListener('world-placement',e=>{for(const el of document.querySelectorAll('[data-world-owner]')){if(el.dataset.worldOwner!==e.detail.owner)continue;const v=views.get(el),player=v?.player||JSON.parse(el.dataset.worldState||'null');if(!player)continue;try{Breakfast.moveItem(player,el.dataset.worldTheme,e.detail.itemId,e.detail.placement);el.dataset.worldState=JSON.stringify(player);const expand=el.closest('.world-scene')?.querySelector('[data-scene-open]');if(expand){const options=JSON.parse(expand.dataset.options||'{}');options.placements=player.placements;expand.dataset.options=JSON.stringify(options);}if(v){for(const [id,group] of v.scene.userData.movable){const at=player.placements?.[id];if(at){group.position.copy(group.parent.worldToLocal(new T.Vector3(at.x,at.y,at.z)));group.updateMatrixWorld(true);}}v.scene.userData.updatePlacement?.();v.dirty=true;}}catch{}}});
globalThis.Budget3D={buildWorld,views};
